/* Select on Radix. The trigger matches .input; the list is a .menu-content. */
.select-trigger { display: flex; align-items: center; justify-content: space-between; gap: var(--s3); width: 100%; min-width: 0; min-height: var(--control-md); padding: 12px 14px; background: transparent; border: 1px solid var(--foreground); color: var(--foreground); text-align: start; }
.select-trigger[data-placeholder] { color: var(--muted); }
.select-trigger[aria-invalid="true"] { border-color: var(--danger); }
.select-trigger:disabled { opacity: 0.55; cursor: not-allowed; border-color: var(--rule); }
.select-trigger::after { content: "↓"; color: var(--muted); }
.select-content { z-index: var(--z-drawer); min-width: var(--radix-select-trigger-width); max-height: min(320px, var(--radix-select-content-available-height)); overflow: hidden; background: var(--background); color: var(--foreground); border: 1px solid var(--foreground); }
.select-viewport { padding: var(--s1) 0; }
.select-item { display: flex; align-items: center; justify-content: space-between; gap: var(--s4); padding: var(--s2) var(--s4); font-size: var(--text-sm); cursor: pointer; }
.select-item[data-highlighted] { background: var(--foreground); color: var(--background); outline: none; }
.select-item[data-disabled] { opacity: 0.5; pointer-events: none; }
.select-label { padding: var(--s2) var(--s4); font-size: var(--text-xs); text-transform: uppercase; letter-spacing: 0.08em; color: var(--muted); }
.select-trigger.input-sm { min-height: var(--control-sm); padding: 6px 10px; font-size: var(--text-sm); }
.select-trigger.input-lg { min-height: var(--control-lg); padding: 14px 18px; }
.select-trigger[data-invalid] { border-color: var(--danger); }

